import{_ as E,C as r,o as t,c as i,a7 as a,b as d,w as o,a as c,E as A,a8 as s}from"./chunks/framework.BCbKzsgW.js";const b=JSON.parse('{"title":"OAuth 2.0 与 OpenID Connect","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/oauth-oidc.md","filePath":"development/common/authentication/oauth-oidc.md","lastUpdated":1793703140000}'),h={name:"development/common/authentication/oauth-oidc.md"};function l(p,e,B,u,C,f){const n=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="oauth-20-yu-openid-connect" tabindex="-1">OAuth 2.0 与 OpenID Connect <a class="header-anchor" href="#oauth-20-yu-openid-connect" aria-label="Permalink to &quot;OAuth 2.0 与 OpenID Connect&quot;">​</a></h1><p>OAuth 解决客户端获得资源访问授权的问题；OpenID Connect（OIDC）在其上定义用户认证结果。把“拿到了某个平台的 Access Token”直接当作本站用户身份，会遗漏令牌受众、主体来源和账号关联等边界。</p><p>OIDC 定义的身份层和 ID Token 见 <a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">OpenID Connect Core</a>。仅提供 OAuth 的平台，需要使用该平台明确规定的用户信息接口与主体标识规则，不能自行伪造一套 ID Token 解释。</p><h2 id="si-ge-jiao-se" tabindex="-1">四个角色 <a class="header-anchor" href="#si-ge-jiao-se" aria-label="Permalink to &quot;四个角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>在第三方登录中的对应</th></tr></thead><tbody><tr><td>资源所有者</td><td>授予访问权限的用户</td></tr><tr><td>客户端</td><td>希望接入登录或 API 的业务应用</td></tr><tr><td>授权服务器</td><td>验证用户、处理授权并签发令牌的一方</td></tr><tr><td>资源服务器</td><td>接受 Access Token 的 API，如 UserInfo</td></tr></tbody></table><p>OIDC 中提供认证的一方称为 OP，依赖认证结果的应用称为 RP。一个服务可以同时承担多种角色，但它们的验证职责仍应分开。</p><h2 id="shou-quan-ma-liu-cheng" tabindex="-1">授权码流程 <a class="header-anchor" href="#shou-quan-ma-liu-cheng" aria-label="Permalink to &quot;授权码流程&quot;">​</a></h2><p>以有服务端的 Web 应用为例，浏览器传递授权码，应用后端向提供方兑换令牌。登录事务保存预期提供方、<code>state</code>、<code>nonce</code>、PKCE verifier、回跳目标与过期时间，并绑定发起浏览器。</p>',8)),(t(),d(s,null,{default:o(()=>[A(n,{id:"mermaid-67",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E6%B5%8F%E8%A7%88%E5%99%A8%0A%20%20%20%20participant%20A%20as%20%E5%BA%94%E7%94%A8%E5%90%8E%E7%AB%AF%20RP%0A%20%20%20%20participant%20I%20as%20%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BE%9B%E6%96%B9%20OP%0A%20%20%20%20C-%3E%3EA%3A%20%E5%8F%91%E8%B5%B7%E7%99%BB%E5%BD%95%0A%20%20%20%20A-%3E%3EA%3A%20%E5%88%9B%E5%BB%BA%E4%B8%80%E6%AC%A1%E6%80%A7%E7%99%BB%E5%BD%95%E4%BA%8B%E5%8A%A1%0A%20%20%20%20A--%3E%3EC%3A%20%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0%E6%8E%88%E6%9D%83%E7%AB%AF%E7%82%B9%0A%20%20%20%20C-%3E%3EI%3A%20code%20%E6%B5%81%E7%A8%8B%EF%BC%8Copenid%20%E4%B8%8E%E5%85%B3%E8%81%94%E5%8F%82%E6%95%B0%0A%20%20%20%20I-%3E%3EI%3A%20%E7%94%A8%E6%88%B7%E8%AE%A4%E8%AF%81%E4%B8%8E%E5%BF%85%E8%A6%81%E6%8E%88%E6%9D%83%0A%20%20%20%20I--%3E%3EC%3A%20%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0%E6%B3%A8%E5%86%8C%E5%9B%9E%E8%B0%83%3Cbr%3E%E6%90%BA%E5%B8%A6%20code%20%E4%B8%8E%20state%0A%20%20%20%20C-%3E%3EA%3A%20%E8%AF%B7%E6%B1%82%E5%9B%9E%E8%B0%83%E5%9C%B0%E5%9D%80%0A%20%20%20%20A-%3E%3EA%3A%20%E6%A0%A1%E9%AA%8C%E6%B5%8F%E8%A7%88%E5%99%A8%E3%80%81state%20%E4%B8%8E%E9%A2%84%E6%9C%9F%E6%8F%90%E4%BE%9B%E6%96%B9%0A%20%20%20%20A-%3E%3EI%3A%20code%20%E4%B8%8E%20verifier%3Cbr%3E%E6%8C%89%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%B1%BB%E5%9E%8B%E5%AE%8C%E6%88%90%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%AE%A4%E8%AF%81%0A%20%20%20%20I--%3E%3EA%3A%20ID%20Token%20%E4%B8%8E%20Access%20Token%0A%20%20%20%20A-%3E%3EA%3A%20%E9%AA%8C%E8%AF%81%20ID%20Token%20%E4%B8%8E%20nonce%0A%20%20%20%20A-%3E%3EA%3A%20%E6%98%A0%E5%B0%84%E6%9C%AC%E5%9C%B0%E8%B4%A6%E5%8F%B7%E5%B9%B6%E6%A3%80%E6%9F%A5%E7%8A%B6%E6%80%81%0A%20%20%20%20A-%3E%3EA%3A%20%E6%B6%88%E8%B4%B9%E7%99%BB%E5%BD%95%E4%BA%8B%E5%8A%A1%EF%BC%8C%E8%BD%AE%E6%8D%A2%E6%9C%AC%E7%AB%99%E4%BC%9A%E8%AF%9D%0A%20%20%20%20A--%3E%3EC%3A%20%E5%88%9B%E5%BB%BA%E6%9C%AC%E7%AB%99%20Session%3Cbr%3E%E8%B7%B3%E8%BD%AC%E5%88%B0%E5%8F%97%E6%8E%A7%E4%B8%9A%E5%8A%A1%E5%9C%B0%E5%9D%80%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>授权请求使用精确注册的 <code>redirect_uri</code> 与 PKCE challenge。图中自调用表示必须成功的本地处理，任一关联、令牌或账号校验失败都停止登录，不创建正式会话；<code>state</code>、<code>nonce</code> 与 PKCE 的分工见下一节。</p><p>客户端只在后端保存上游令牌时，浏览器最终持有本地 Session Cookie 即可，没必要把上游 Refresh Token 再交给页面脚本。</p><h2 id="statenonce-yu-pkce" tabindex="-1">state、nonce 与 PKCE <a class="header-anchor" href="#statenonce-yu-pkce" aria-label="Permalink to &quot;state、nonce 与 PKCE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>关联对象</th><th>验证位置</th></tr></thead><tbody><tr><td><code>state</code></td><td>本次登录发起与回调、浏览器上下文</td><td>回调入口</td></tr><tr><td><code>nonce</code></td><td>本次 OIDC 请求与 ID Token</td><td>ID Token 校验</td></tr><tr><td>PKCE</td><td>授权请求与授权码兑换方</td><td>Token Endpoint</td></tr></tbody></table><p>应用统一使用授权码与 PKCE <code>S256</code>，同时保留一次性 <code>state</code> 和 OIDC <code>nonce</code>，是便于审计的设计选择。标准对不同条件允许使用的防护组合有更细规定，见 <a href="https://www.rfc-editor.org/rfc/rfc9700.html#section-2.1" target="_blank" rel="noreferrer">RFC 9700 §2.1</a>；不能把 PKCE 解释成无条件替代所有请求关联检查。</p><p><a href="https://www.rfc-editor.org/rfc/rfc7636.html#section-4.2" target="_blank" rel="noreferrer">PKCE 的 <code>S256</code> 计算</a>为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>code_challenge = BASE64URL(SHA256(ASCII(code_verifier)))</span></span></code></pre></div><p>verifier 使用密码学安全随机数，每次授权事务独立生成，长度与编码按 RFC 7636；不把固定字符串、用户 ID 或普通 UUID 拼接当作替代。服务端保存原值用于兑换，授权请求只带 challenge。</p><h2 id="id-token-yan-zheng" tabindex="-1">ID Token 验证 <a class="header-anchor" href="#id-token-yan-zheng" aria-label="Permalink to &quot;ID Token 验证&quot;">​</a></h2><p>采用成熟 OIDC 库，按 <a href="https://openid.net/specs/openid-connect-core-1_0.html#IDTokenValidation" target="_blank" rel="noreferrer">Core §3.1.3.7</a>与提供方元数据进行验证。应用至少需要明确以下配置与检查：</p><ul><li>信任的 <code>issuer</code>、签名算法与该 issuer 的密钥来源。</li><li><code>aud</code> 是否包含本客户端，多个受众时按规范处理 <code>azp</code>。</li><li>时间声明是否有效，<code>nonce</code> 是否匹配此次请求。</li><li>要求近期认证或特定强度时，检查约定的 <code>auth_time</code>、<code>acr</code> 等结果。</li><li>如再读取 UserInfo，其 <code>sub</code> 必须与 ID Token 对应主体一致。</li></ul><p>不能根据客户端请求参数随意信任一个新 issuer，也不能根据未验证令牌中的地址去发现密钥。多身份提供方要绑定发起时的配置，并防范 issuer 混淆；发现元数据与重定向地址同样需要受信配置。</p><h2 id="hui-diao-shi-yi-ci-xing-ye-wu-shi-wu" tabindex="-1">回调是一次性业务事务 <a class="header-anchor" href="#hui-diao-shi-yi-ci-xing-ye-wu-shi-wu" aria-label="Permalink to &quot;回调是一次性业务事务&quot;">​</a></h2><p>登录事务只保存随机 <code>state</code>，却不绑定发起浏览器，也可能接受攻击者从另一个浏览器搬来的回调。可通过安全关联 Cookie 或服务端预登录会话绑定，并设置短有效期与一次性消费。</p><p>并发标签页不能共享唯一一条“当前 state”记录。使用以事务 ID 为键的记录集合，在控制数量的前提下允许多个独立登录流程。</p><p>授权码重复兑换通常应失败，应用回调也要防止重复创建账号或重复绑定。可将事务标记为处理中并原子消费；外部兑换超时出现未知结果时，选择安全失败并重新登录，不无限重放回调。</p><p>回跳地址保存在服务端或使用严格允许列表。<code>return_to</code> 不能直接允许任意绝对 URL，也要处理 <code>//evil.example</code>、编码绕过和协议差异，避免本站成为开放重定向器。</p><h2 id="wai-bu-zhang-hao-ying-she" tabindex="-1">外部账号映射 <a class="header-anchor" href="#wai-bu-zhang-hao-ying-she" aria-label="Permalink to &quot;外部账号映射&quot;">​</a></h2><p>首次登录先按 <code>(issuer, sub)</code> 查找绑定。未绑定时，可以进入注册流程或让用户先登录现有账号再显式绑定；不要仅凭邮箱相同自动接管已有账号。</p><p>账号被冻结、企业成员被移除或外部身份被解绑后，应用必须拒绝建立对应登录态。外部认证成功只证明提供方的认证判断，本地业务状态仍由本站控制。详细流程见<a href="./account-lifecycle.html">账号模型与生命周期</a>。</p><h2 id="ke-hu-duan-chai-yi-yu-jiu-mo-shi" tabindex="-1">客户端差异与旧模式 <a class="header-anchor" href="#ke-hu-duan-chai-yi-yu-jiu-mo-shi" aria-label="Permalink to &quot;客户端差异与旧模式&quot;">​</a></h2><p>原生应用优先通过系统浏览器完成授权，回调与安全存储遵循平台要求；SPA 不携带可保密的固定 secret。后台能保密的 Web 客户端也应使用 PKCE，客户端认证与 PKCE 保护的是不同边界。</p><p>新设计不采用隐式流程返回 Access Token，也不收集用户在提供方的密码来执行密码授权模式。RFC 9700 对隐式授权给出限制，对资源所有者密码凭据授权规定不得使用；旧系统迁移需要核对兼容性，不能只替换参数名称。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>OpenID Foundation：<a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">OpenID Connect Core 1.0</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc7636.html" target="_blank" rel="noreferrer">RFC 7636 — PKCE</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc9700.html" target="_blank" rel="noreferrer">RFC 9700 — OAuth 2.0 Security Best Current Practice</a></li></ul>',25))])}const k=E(h,[["render",l]]);export{b as __pageData,k as default};
